import { useState, useCallback, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [draft, setDraft] = useState('');

  const commitTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange]
  );

  const addTag = useCallback(() => {
    const value = draft.trim();
    if (!value || tags.includes(value)) {
      setDraft('');
      return;
    }
    commitTags([...tags, value]);
    setDraft('');
  }, [draft, tags, commitTags]);

  const removeTag = useCallback(
    (tag: string) => {
      commitTags(tags.filter((item) => item !== tag));
    },
    [tags, commitTags]
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  return (
    <div>
      <JxInputField
        label="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        helperText="Enter — добавить тег, Backspace на пустом поле — удалить последний"
      />
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-radius-sm)', marginTop: 'var(--jx-radius-sm)' }}>
        {tags.map((tag) => (
          <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
            {tag}
          </JxChip>
        ))}
      </div>
    </div>
  );
}

